\set ON_ERROR_STOP on

CREATE SCHEMA IF NOT EXISTS auth;
CREATE SCHEMA IF NOT EXISTS private;

DO $roles$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN CREATE ROLE authenticated NOLOGIN; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='anon') THEN CREATE ROLE anon NOLOGIN; END IF;
END;
$roles$;

CREATE OR REPLACE FUNCTION auth.uid()
RETURNS uuid LANGUAGE sql STABLE
AS $fn$ SELECT NULLIF(current_setting('request.jwt.claim.sub', true), '')::uuid $fn$;

CREATE TABLE public.products (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id uuid NOT NULL,
  name text NOT NULL,
  price numeric NOT NULL
);

CREATE TABLE public.sales (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  invoice_number text NOT NULL UNIQUE,
  subtotal numeric NOT NULL,
  discount numeric NOT NULL DEFAULT 0,
  tax numeric NOT NULL DEFAULT 0,
  total numeric NOT NULL,
  payment_status text NOT NULL,
  status text NOT NULL,
  organization_id uuid NOT NULL,
  store_id uuid NOT NULL
);

CREATE TABLE public.sale_items (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  sale_id bigint NOT NULL REFERENCES public.sales(id),
  product_id bigint REFERENCES public.products(id),
  product_name text NOT NULL,
  unit_price numeric NOT NULL,
  quantity integer NOT NULL,
  discount numeric NOT NULL DEFAULT 0,
  total numeric NOT NULL,
  unit_cost numeric,
  cost_total numeric
);

CREATE TABLE public.store_products (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  store_id uuid NOT NULL,
  product_id bigint NOT NULL REFERENCES public.products(id),
  quantity integer NOT NULL,
  average_cost numeric NOT NULL DEFAULT 0,
  cost_known boolean NOT NULL DEFAULT false,
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(store_id, product_id)
);

CREATE TABLE public.inventory_movements (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  product_id bigint,
  movement_type text NOT NULL,
  quantity_change integer NOT NULL,
  reference_type text,
  reference_id bigint,
  notes text,
  organization_id uuid NOT NULL,
  store_id uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.payments (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  sale_id bigint NOT NULL REFERENCES public.sales(id),
  amount numeric NOT NULL,
  payment_method text NOT NULL DEFAULT 'cash',
  reference text,
  paid_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.sale_returns (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  sale_id bigint NOT NULL REFERENCES public.sales(id),
  organization_id uuid NOT NULL,
  store_id uuid NOT NULL,
  reason text,
  notes text,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.sale_return_items (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  return_id bigint NOT NULL REFERENCES public.sale_returns(id),
  sale_item_id bigint NOT NULL REFERENCES public.sale_items(id),
  product_id bigint,
  quantity integer NOT NULL,
  unit_price numeric NOT NULL,
  refund_amount numeric NOT NULL DEFAULT 0
);

CREATE TABLE public.refunds (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  sale_id bigint NOT NULL REFERENCES public.sales(id),
  organization_id uuid NOT NULL,
  store_id uuid NOT NULL,
  amount numeric NOT NULL,
  payment_method text NOT NULL,
  reference text,
  reason text,
  refunded_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.audit_logs (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id uuid NOT NULL,
  store_id uuid NOT NULL,
  action text NOT NULL,
  entity_type text NOT NULL,
  entity_id text NOT NULL,
  metadata jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE OR REPLACE FUNCTION private.is_org_store_member(p_organization_id uuid, p_store_id uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public','private'
AS $function$ SELECT coalesce(nullif(current_setting('test.is_org_store_member', true), '')::boolean, true) $function$;

CREATE OR REPLACE FUNCTION private.has_org_permission(p_organization_id uuid, p_permission_code text)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public','private'
AS $function$ SELECT coalesce(nullif(current_setting('test.has_org_permission', true), '')::boolean, true) $function$;

CREATE OR REPLACE FUNCTION private.write_audit_log(
  p_organization_id uuid, p_store_id uuid, p_action text, p_entity_type text, p_entity_id text, p_metadata jsonb
)
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path TO ''
AS $function$
DECLARE v_id bigint;
BEGIN
  INSERT INTO public.audit_logs(organization_id,store_id,action,entity_type,entity_id,metadata)
  VALUES(p_organization_id,p_store_id,p_action,p_entity_type,p_entity_id,p_metadata)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$;

CREATE OR REPLACE FUNCTION private.refresh_sale_return_status(p_sale_id bigint)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','private'
AS $function$
DECLARE v_sold integer; v_returned integer; v_status text;
BEGIN
  SELECT coalesce(sum(quantity),0) INTO v_sold FROM public.sale_items WHERE sale_id=p_sale_id;
  SELECT coalesce(sum(sri.quantity),0) INTO v_returned
  FROM public.sale_return_items sri JOIN public.sale_returns sr ON sr.id=sri.return_id
  WHERE sr.sale_id=p_sale_id;
  v_status := CASE WHEN v_returned>=v_sold THEN 'returned' WHEN v_returned>0 THEN 'partially_returned' ELSE 'completed' END;
  UPDATE public.sales SET status=v_status WHERE id=p_sale_id;
  RETURN v_status;
END;
$function$;

CREATE OR REPLACE FUNCTION public.return_sale_items(
  p_organization_id uuid, p_store_id uuid, p_sale_id bigint, p_items jsonb,
  p_reason text DEFAULT NULL, p_notes text DEFAULT NULL, p_refund_amount numeric DEFAULT 0,
  p_refund_payment_method text DEFAULT 'cash', p_refund_reference text DEFAULT NULL
)
RETURNS jsonb LANGUAGE plpgsql SET search_path TO 'public','private'
AS $function$
BEGIN
  RETURN private.return_sale_items(p_organization_id,p_store_id,p_sale_id,p_items,p_reason,p_notes,p_refund_amount,p_refund_payment_method,p_refund_reference);
END;
$function$;
